const request = $('ClubSpark Package Import Queue Export Webhook').first()?.json ?? $input.first()?.json ?? {};
const body = request.body ?? request;
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const toArray = (value) => Array.isArray(value) ? value : value === null || value === undefined ? [] : [value];
const parseInteger = (value) => {
  const parsed = Number.parseInt(String(value ?? '').trim(), 10);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
};
const rawItemValues = [
  ...toArray(body.item_id),
  ...toArray(body.item_ids)
];
const itemIds = [];
const seen = new Set();
for (const rawValue of rawItemValues) {
  const parts = String(rawValue ?? '').replace(/\r/g, '').split(/[\n,;]+/);
  for (const part of parts) {
    const parsed = parseInteger(part);
    if (!parsed || seen.has(parsed)) continue;
    seen.add(parsed);
    itemIds.push(parsed);
  }
}
const batchId = parseInteger(body.batch_id ?? body.batchId);
const targetMembership = clean(body.target_membership ?? body.targetMembership);
const defaultCountry = clean(body.default_country) || 'United Kingdom';
const filePrefix = clean(body.file_prefix) || 'clubspark-package-import';
const safeTarget = targetMembership.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'package';
const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const fileName = `${filePrefix}-${safeTarget}-${stamp}.xlsx`;
let errorMessage = '';
if (!batchId) {
  errorMessage = 'Batch ID is required.';
} else if (!targetMembership) {
  errorMessage = 'Target package is required.';
} else if (!itemIds.length) {
  errorMessage = 'Select at least one queued package-import row.';
}
return [{ json: { batch_id: batchId, target_membership: targetMembership, item_ids: itemIds, default_country: defaultCountry, file_prefix: filePrefix, file_name: fileName, error_message: errorMessage } }];

const request = $('Resolve Export Request').first()?.json ?? {};
const rows = $input.all().map((item) => item.json ?? {});
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
if (!rows.length) {
  return [{ json: { error_message: 'No rows were returned for export.' } }];
}
const errorMessage = clean(rows[0].error_message);
if (errorMessage) {
  return [{ json: { error_message: errorMessage } }];
}
const stripBrackets = (value) => clean(value).replace(/[\[\]]/g, '');
const formatGender = (value) => {
  const raw = clean(value).toLowerCase();
  if (raw === 'male') return 'M';
  if (raw === 'female') return 'F';
  return clean(value);
};
const formatNumeric = (value) => {
  if (value === null || value === undefined || value === '') return '';
  const parsed = Number.parseFloat(String(value).replace(/[^0-9.-]+/g, ''));
  if (Number.isNaN(parsed)) return clean(value);
  return Number.isInteger(parsed) ? String(parsed) : String(parsed).replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');
};
const formatKeyPin = (value) => {
  const raw = clean(value);
  return raw === '[]' ? '' : raw;
};
const defaultCountry = clean(request.default_country) || 'United Kingdom';
const output = [];
const missingIds = [];
for (const row of rows) {
  const contactId = stripBrackets(row.member_unique_id);
  if (!contactId) {
    missingIds.push(clean(row.member || row.id));
    continue;
  }
  output.push({
    json: {
      ContactID: contactId,
      FirstName: clean(row.member_first_name),
      LastName: clean(row.member_last_name),
      EmailAddress: clean(row.member_email),
      StartDate: clean(row.member_start_date),
      ExpiryDate: clean(row.member_expiry_date),
      Cost: formatNumeric(row.member_cost),
      Paid: formatNumeric(row.member_paid),
      GiftAid: clean(row.member_gift_aid),
      Gender: formatGender(row.member_gender),
      BirthDate: clean(row.member_birth_date),
      HomeNumber: clean(row.member_home_number),
      WorkNumber: clean(row.member_work_number),
      MobileNumber: clean(row.member_mobile_number),
      EmergencyPhoneNumber: clean(row.member_emergency_phone_number),
      PostCode: clean(row.member_postcode),
      Address1: clean(row.member_address_1),
      Address2: clean(row.member_address_2),
      Address3: clean(row.member_address_3),
      Town: clean(row.member_town),
      County: clean(row.member_county),
      Country: clean(row.member_country) || defaultCountry,
      Occupation: clean(row.member_occupation),
      BritishTennisNumber: clean(row.british_tennis_number),
      DateJoinedVenue: clean(row.member_date_joined_venue),
      MedicalHistory: clean(row.member_medical_history),
      Source: clean(row.member_source),
      KeyPinNumber: formatKeyPin(row.member_key_pin_number),
      TagsProvided: clean(row.member_tags_provided),
      _queueItemId: clean(row.id),
      _member: clean(row.member),
      _targetMembership: clean(row.target_membership),
      _clubsparkPackageId: clean(row.clubspark_package_id),
      _clubsparkImportUrl: clean(row.clubspark_import_url),
      _fileName: clean(request.file_name)
    }
  });
}
if (missingIds.length) {
  return [{ json: { error_message: `Missing ClubSpark Contact ID for: ${missingIds.join(', ')}` } }];
}
return output;

const item = $input.first()?.json ?? {};
const message = item.error_message || 'Unable to build the ClubSpark package import workbook.';
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ClubSpark Package Export Failed</title><style>body{margin:0;padding:24px;background:#f7f8fc;font-family:Lato,'Helvetica Neue',Arial,sans-serif;color:#2e3d4e}.panel{max-width:760px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:18px;box-shadow:0 18px 40px rgba(53,72,91,.08);padding:28px}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:999px;text-decoration:none;font-weight:700;background:linear-gradient(135deg,#509ee3 0%,#2f80d8 100%);color:#fff}</style></head><body><div class="panel"><h1>ClubSpark Package Export Failed</h1><p>${escapeHtml(message)}</p><p><a class="button" href="javascript:history.back()">Back</a></p></div></body></html>`;
return [{ json: { html } }];

const headers = [
  'ContactID','FirstName','LastName','EmailAddress','StartDate','ExpiryDate','Cost','Paid','GiftAid','Gender','BirthDate','HomeNumber','WorkNumber','MobileNumber','EmergencyPhoneNumber','PostCode','Address1','Address2','Address3','Town','County','Country','Occupation','BritishTennisNumber','DateJoinedVenue','MedicalHistory','Source','KeyPinNumber','TagsProvided'
];
return $input.all().map((item) => {
  const row = item.json ?? {};
  const exportRow = {};
  for (const header of headers) exportRow[header] = row[header] ?? '';
  return { json: exportRow };
});
